  "bibleHelps.voices.disputed": "ድንበር አከራካሪ ነው",
  "bibleParticipants.p1.name": "ስሞች ተጠብቀዋል",
  "bibleParticipants.p1.description": "ምንጩ አንድን ሰው በሚሰይምበት፣ ትርጉሙ የተስማማውን ስማቸው አለው፦ እንደ render.person.Peter ያለ ውሳኔ፣ ወይም የቃላት ግቤት።",
  "bibleParticipants.p2.name": "በፋይሉ አንድ ስም",
  "bibleParticipants.p2.description": "እያንዳንዱ ሰው፣ ቡድን ወይም ቦታ በምንጩ ተመሳሳይ የስም ቅርጽ በሚጠቀም እያንዳንዱ ጥቅስ ተመሳሳይ ስም አለው። በፋይል ፍተሻ ይሮጣል።",
  "bibleParticipants.p3.name": "ተመሳሳይ ስሞች ተለይተዋል",
  "bibleParticipants.p3.description": "ምንጩ ተመሳሳይ ስም ካላቸው በርካታ ሰዎች አንዱን በሚሰይምበት (ስድስት ማርያሞች፣ ዘጠኝ ስምዖኖች)፣ ትርጉሙ የዚያን ሰው ስም ይጠቀማል፣ የሌላውን አይደለም።",
  "bibleParticipants.p4.name": "የስም ቅርጽ ተጠብቋል",
  "bibleParticipants.p4.description": "ምንጩ አንድ የስም ቅርጽ ሲጠቀም (ኬፋ፣ ስምዖን አይደለም) እና ፕሮጀክቱ ለእያንዳንዱ ቅርጽ ስም ሲኖረው፣ ትርጉሙ ለዚያ ቅርጽ ያለውን ስም ይጠቀማል።",
  "bibleParticipants.p5.name": "ምንጩ የሌሉት ስሞች የሉም",
  "bibleParticipants.p5.description": "ትርጉሙ የጥቅሱ ምንጭ በስም፣ እንደ ተውላጠ ስም ወይም እንደ የግስ ርዕሰ ጉዳይ የማይጠቅሰውን ሰው አይሰይምም። ከፊት ወይም ከኋላ ያለው ጥቅስ ርዕሰ ጉዳይም ይቆጠራል።",
  "bibleParticipants.p6.name": "የተጠቆመ ርዕሰ ጉዳይ በትክክል ተሰይሟል",
  "bibleParticipants.p6.description": "ምንጩ ማንም በማይሰይምበት እና ማን እንደሚሠራ ብቻ በሚጠቁምበት («ይላል»)፣ ትርጉሙ የሚጨምረው ስም የዚያ ሰው ስም ነው።",
  "bibleParticipants.p8.description": "በምንጩ ያለ እያንዳንዱ «አንተ» ለአንድ ሰው ሲናገር፣ ወይም እያንዳንዱ ለበርካታ ሲናገር፣ ትርጉሙ ከቋንቋ መገለጫው ያንን ቁጥር ያለው «አንተ» ይጠቀማል፣ ሌላውን አይደለም።",
  "bibleParticipants.p9.name": "የሚያካትት ወይም የሚያገለል «እኛ»",
  "bibleParticipants.p9.description": "«እኛ» የሚነገራቸውን ሰዎች ሲያካትት፣ ወይም ሲተዋቸው፣ ትርጉሙ ከቋንቋ መገለጫው የሚያካትተውን ወይም የሚያገለለውን «እኛ» ይጠቀማል።",
  "bibleParticipants.p10.name": "የሁለት፣ የሦስት እና የጥቂት ቅርጾች",
  "bibleParticipants.p10.description": "ተውላጠ ስም ሁለት፣ ሦስት ወይም ጥቂት ሰዎችን ሲያመለክት፣ ትርጉሙ ከቋንቋ መገለጫው ለዚያ ቁጥር ያለውን ቅርጽ ይጠቀማል።",
  "bibleParticipants.p14.name": "ጌታ እና መንፈስ",
  "bibleParticipants.p14.description": "κύριος ኢየሱስን ወይም እግዚአብሔርን ሲያመለክት፣ ወይም πνεῦμα መንፈስ ቅዱስን ሲያመለክት፣ ትርጉሙ ለእያንዳንዱ የፕሮጀክቱን አቀራረብ ይጠቀማል።",
  "bibleParticipants.p15.name": "ለእግዚአብሔር አቢይ ፊደላት",
  "bibleParticipants.p15.description": "የቤት ቅጥ ለእግዚአብሔር፣ ለኢየሱስ እና ለመንፈስ ቅዱስ ተውላጠ ስሞችን በአቢይ ፊደል ሲጀምር፣ እነዚያ ተውላጠ ስሞች በአቢይ ፊደል ይጀምራሉ።",
  "bibleParticipants.x3.name": "የተደጋገሙ ጥቅሶች ተመሳሳይ",
  "bibleParticipants.x3.description": "ምንጩ በፋይሉ ጥቅስ ሲደግም፣ ትርጉሙ በእያንዳንዱ ጊዜ በተመሳሳይ መንገድ ያቀርበዋል። በፋይል ፍተሻ ይሮጣል።",
  "bibleParticipants.x4.name": "ውሳኔዎች ተጠብቀዋል",
  "bibleParticipants.x4.description": "ፕሮጀክቱ በንባብ ውስጥ «እኛ» አድማጩን ያካትት እንደሆነ ከወሰነ (የማካተት ውሳኔ)፣ በዚያ ንባብ ያለ እያንዳንዱ «እኛ» የተወሰነውን ቅርጽ ይጠቀማል።",
  "bibleParticipants.needs.agreedNames": "ያስፈልጋል፦ የተስማሙ ስሞች፣ ከውሳኔዎች (render.…) ወይም ከቃላት ግቤቶች",
  "bibleParticipants.needs.nameForms": "ያስፈልጋል፦ ለአንድ ስም ሁለት ቅርጾች ውሳኔ (render.….form.…)",
  "bibleParticipants.needs.secondPersonForms": "ያስፈልጋል፦ በቋንቋ መገለጫ ውስጥ ነጠላ እና ብዙ «አንተ» ቅርጾች",
  "bibleParticipants.needs.secondPersonSame": "አይውልም፦ በቋንቋ መገለጫ «አንተ» ለአንድ ሰው እና ለበርካታ ተመሳሳይ ነው",
  "bibleParticipants.needs.clusivityForms": "ያስፈልጋል፦ በቋንቋ መገለጫ ውስጥ የሚያካትት እና የሚያገለል «እኛ» ቅርጾች",
  "bibleParticipants.needs.clusivitySame": "አይውልም፦ በቋንቋ መገለጫ «እኛ» ከአድማጭ ጋርም ያለ እሱም ተመሳሳይ ነው",
  "bibleParticipants.needs.groupNumberForms": "ያስፈልጋል፦ በቋንቋ መገለጫ ውስጥ የሁለት፣ የሦስት ወይም የጥቂት ቅርጾች",
  "bibleParticipants.needs.groupNumberNone": "አይውልም፦ የቋንቋ መገለጫ የሁለት፣ የሦስት ወይም የጥቂት ቅርጽ የለውም",
  "bibleParticipants.needs.divineNames": "ያስፈልጋል፦ በቋንቋ መገለጫ (የእግዚአብሔር ስሞች) ወይም እንደ ውሳኔዎች የκύριος አቀራረቦች",
  "bibleParticipants.needs.deityCapitals": "ያስፈልጋል፦ በቋንቋ መገለጫ (የእግዚአብሔር ስሞች) ለእግዚአብሔር የአቢይ ፊደል ደንብ",
  "bibleParticipants.needs.deityCapitalsOff": "አይውልም፦ የቤት ቅጥ ለእግዚአብሔር ተውላጠ ስሞችን በትንሽ ፊደል ያቆያል",
  "bibleParticipants.needs.alignment": "ያስፈልጋል፦ በግሪክ እና በትርጉም መካከል የቃል አሰላለፍ፣ ይህ ፕሮጀክት የሌለው",
  "bibleParticipants.needs.clusivityDecisions": "ያስፈልጋል፦ በንባብ ውስጥ ስለ «እኛ» ውሳኔ (clusivity.…)",
  "bibleParticipants.reason.nameMissing": "ምንጩ እዚህ {name}ን ይሰይማል፣ ነገር ግን ትርጉሙ ከተስማሙ ስሞች ({renderings}) አንዱንም የለውም።",
  "bibleParticipants.reason.nameMissingPronoun": "ምንጩ እዚህ {name}ን ይሰይማል፣ ነገር ግን ትርጉሙ ከተስማሙ ስሞች ({renderings}) አንዱንም የለውም። ተውላጠ ስም እዚህ ትክክል ሊሆን ይችላል፣ ምክንያቱም አውዱ ይህን ሰው አስቀድሞ ይሰይማል።",
  "bibleParticipants.reason.nameVariantDifferent": "ትርጉሙ እዚህ {name}ን «{found}» ይላል፣ ነገር ግን በቀሪው ፋይል በምንጩ ያለው ተመሳሳይ ስም «{usual}» ነው።",
  "bibleParticipants.reason.nameVariantNone": "ምንጩ እዚህ {name}ን ይሰይማል፣ ነገር ግን ትርጉሙ ቀሪው ፋይል የሚጠቀመውን ስም «{usual}» የለውም።",
  "bibleParticipants.reason.homonymName": "ምንጩ እዚህ {name}ን ይሰይማል፣ ነገር ግን ትርጉሙ «{found}» አለው፣ የ{other} ስም የሆነው።",
  "bibleParticipants.reason.nameFormMissing": "ምንጩ እዚህ {name}ን «{form}» ይላል። ፕሮጀክቱ ያንን ቅርጽ «{rendering}» ያቀርባል፣ እና ትርጉሙ የለውም።",
